-- ============================================================
-- SISGESC — Stress Test | Volume Alto (v2 — corrigido)
-- Correções: pagamento via contrato+matricula (sem ERROR 1442)
-- Alunos: 300 | Funcs: 20 | Mensalidades: ~3600
-- Ponto: ~20000 | Frequência: ~9000
-- ============================================================

USE erp_escolar;

-- ============================================================
-- BENCHMARK 0: estado ANTES da carga
-- ============================================================
SELECT 'ANTES' AS fase,
       (SELECT COUNT(*) FROM aluno)       AS alunos,
       (SELECT COUNT(*) FROM funcionario) AS funcionarios,
       (SELECT COUNT(*) FROM matricula)   AS matriculas,
       (SELECT COUNT(*) FROM ponto)       AS pontos,
       (SELECT COUNT(*) FROM frequencia)  AS frequencias,
       (SELECT COUNT(*) FROM mensalidade) AS mensalidades,
       (SELECT COUNT(*) FROM pagamento)   AS pagamentos;

-- ============================================================
-- SEÇÃO 1: 300 novos alunos
-- ============================================================

-- ============================================================
-- SEÇÃO 2: 20 novos funcionários e professores
-- ============================================================



-- ============================================================
-- SEÇÃO 3: 300 matrículas e contratos
-- ============================================================

   valor_mensalidade_referencia, status)
SELECT m.pk_id_matricula, '2024-02-01', '2024-02-01', 1800.00, 'Ativo'
FROM matricula m
WHERE m.fk_rga BETWEEN 'A0001000' AND 'A0001299'
  AND m.fk_curso = 'ADS'
  AND NOT EXISTS (
    SELECT 1 FROM contrato c WHERE c.fk_id_matricula = m.pk_id_matricula);

-- ============================================================
-- SEÇÃO 4: ~3600 mensalidades
-- CORREÇÃO v2: todas inseridas como 'Pendente'.
-- O trigger TR_pagamento_quita_mensalidade_insert cuida do status
-- automaticamente quando o pagamento for inserido na Seção 5.
-- ============================================================
SELECT c.pk_id_contrato, '2024-01', 1800.00, 0.00, '2024-01-10', 'Pendente'
FROM contrato c
JOIN matricula m ON m.pk_id_matricula = c.fk_id_matricula
WHERE m.fk_rga BETWEEN 'A0001000' AND 'A0001299'
  AND NOT EXISTS (
    SELECT 1 FROM mensalidade ms
    WHERE ms.fk_id_contrato = c.pk_id_contrato AND ms.periodo = '2024-01');

