-- ============================================================
-- SEÇÃO 7: Frequência — 100 alunos × 90 aulas na turma 1
-- TR_frequencia_aluno_na_turma usa PK de matricula_turma → eficiente
-- ============================================================
SELECT m.pk_id_matricula, 1, 'Cursando'
FROM matricula m
WHERE m.fk_rga BETWEEN 'A0001000' AND 'A0001099'
  AND m.fk_curso = 'ADS'
  AND NOT EXISTS (
    SELECT 1 FROM matricula_turma mt
    WHERE mt.fk_id_matricula = m.pk_id_matricula AND mt.fk_id_turma = 1);

SELECT mt.fk_id_matricula, 1, '2024-02-05', TRUE
FROM matricula_turma mt
WHERE mt.fk_id_turma = 1
  AND NOT EXISTS (
    SELECT 1 FROM frequencia f
    WHERE f.fk_id_matricula = mt.fk_id_matricula
      AND f.fk_id_turma = 1 AND f.data_aula = '2024-02-05');

