-- ============================================================
-- BENCHMARK 1: estado DEPOIS da carga
-- Esperado: pagamentos = alunos × 8 meses + 42 originais
-- ============================================================
SELECT 'DEPOIS' AS fase,
       (SELECT COUNT(*) FROM aluno)       AS alunos,
       (SELECT COUNT(*) FROM funcionario) AS funcionarios,
       (SELECT COUNT(*) FROM matricula)   AS matriculas,
       (SELECT COUNT(*) FROM ponto)       AS pontos,
       (SELECT COUNT(*) FROM frequencia)  AS frequencias,
       (SELECT COUNT(*) FROM mensalidade) AS mensalidades,
       (SELECT COUNT(*) FROM pagamento)   AS pagamentos;

-- ============================================================
-- VALIDAÇÃO: toda mensalidade 'Pago' deve ter pagamento registrado
-- (mesmo teste da Fase 6 — agora com volume alto)
-- Resultado esperado: 0 linhas
-- ============================================================
SELECT ms.fk_id_contrato, ms.periodo, ms.status AS status_mensalidade,
       p.pk_id_pagamento AS id_pagamento
FROM mensalidade ms
LEFT JOIN pagamento p ON p.fk_id_contrato = ms.fk_id_contrato
                     AND p.periodo = ms.periodo
                     AND p.status = 'Pago'
WHERE ms.status = 'Pago' AND p.pk_id_pagamento IS NULL
LIMIT 5; -- 0 linhas = trigger funcionou corretamente para todos os pagamentos

-- ============================================================
-- EXPLAIN das queries críticas com volume alto
-- ============================================================

-- Trigger ponto: usa PRIMARY(fk_rgf, data_hora) em reverse — sem full scan
EXPLAIN
SELECT tipo FROM ponto
WHERE fk_rgf = 'F0100'
ORDER BY data_hora DESC LIMIT 1;

-- Trigger matricula_ativa: usa FK index em fk_rga
EXPLAIN
SELECT COUNT(*) FROM matricula
WHERE fk_rga = 'A0001000' AND fk_curso = 'ADS' AND status = 'Cursando';

-- vw_inadimplencia com 300 alunos e 3600 mensalidades
EXPLAIN SELECT * FROM vw_inadimplencia LIMIT 10;

-- ============================================================
-- PROFILING: tempo real das queries principais
-- ============================================================
SET profiling = 1;

SELECT aluno, meses_em_aberto, total_em_aberto FROM vw_inadimplencia LIMIT 20;

SELECT ms.periodo,
       COUNT(*) AS qtd_mensalidades,
       SUM(ms.valor_base - ms.valor_desconto)  AS receita_esperada,
       SUM(CASE WHEN ms.status = 'Pago'
           THEN ms.valor_base - ms.valor_desconto ELSE 0 END) AS receita_realizada
FROM mensalidade ms
GROUP BY ms.periodo ORDER BY ms.periodo;

SELECT fk_rgf, COUNT(*) AS total_registros,
       SUM(CASE WHEN tipo = 'Entrada' THEN 1 ELSE 0 END) AS entradas
FROM ponto WHERE fk_rgf BETWEEN 'F0100' AND 'F0119'
GROUP BY fk_rgf ORDER BY entradas DESC;

SHOW PROFILES;

